//! Model-agnostic generative UI gallery system.
//!
//! This crate implements a model-agnostic inference loop that reads sealed plugin blobs,
//! accepts operator guidance via Antigravity chat UI, and generates json-render.dev specs
//! rendered by the existing DSL interpreter.
//!
//! # Architecture
//!
//! 1. **Context Assembler** — Gathers baseline context (blobs, docs, catalog)
//! 2. **Inference Loop** — Calls ZeroClaw `/v1/chat/completions` with tool support
//! 3. **Spec Validator** — Validates generated specs against grammar
//! 4. **Gallery Admission** — Admits validated specs to catalog store
//!
//! # Model Agnosticism
//!
//! No model-specific code. Any model exposed through ZeroClaw can be used. Model selection
//! is ZeroClaw's responsibility via the zeroclaw plugin's `selected_provider` and
//! `selected_model` fields.

pub mod context;
pub mod inference;
pub mod validator;
pub mod admission;
pub mod tools;

pub use context::{GenerationContext, SchemaPayload};
pub use inference::InferenceLoop;
pub use validator::SpecValidator;
pub use admission::GalleryAdmission;

/// Gallery generation configuration
#[derive(Debug, Clone, serde::Deserialize)]
pub struct GalleryGenConfig {
    /// Target number of specs to generate (default: 200)
    pub target_count: usize,

    /// Maximum stable-core elements to protect (default: 40)
    pub stable_core_max: usize,

    /// ZeroClaw HTTP endpoint (default: "http://localhost:8082")
    pub zeroclaw_endpoint: String,

    /// Enable MCP tool layer for cross-blob discovery
    pub enable_mcp: bool,

    /// Enable Qdrant semantic search
    pub enable_qdrant: bool,

    /// Maximum inference turns per spec (default: 10)
    pub max_turns: usize,
}

impl Default for GalleryGenConfig {
    fn default() -> Self {
        Self {
            target_count: 200,
            stable_core_max: 40,
            zeroclaw_endpoint: "http://localhost:8082".to_string(),
            enable_mcp: false,
            enable_qdrant: false,
            max_turns: 10,
        }
    }
}

//! Context assembler for gallery generation.
//!
//! Gathers baseline context for the inference loop:
//! - Plugin schemas from sealed blobs
//! - Static documentation (access-instructions, catalog, grammar)
//! - Operator guidance from Antigravity chat

use anyhow::Result;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;

/// Assembled context for a single generation run.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GenerationContext {
    /// Baseline: all plugin schemas from blobs
    pub schemas: Vec<SchemaPayload>,

    /// Static docs: access-instructions.md content
    pub access_instructions: String,

    /// Static docs: json-render-catalog.md content  
    pub catalog_docs: String,

    /// Static docs: spec-grammar.md content
    pub grammar_docs: String,

    /// Universal prompt (vague, goal-oriented)
    pub universal_prompt: String,

    /// Operator guidance from Antigravity chat
    pub operator_guidance: Option<String>,

    /// MCP toggle enabled
    pub mcp_enabled: bool,

    /// Qdrant toggle enabled
    pub qdrant_enabled: bool,
}

/// Schema payload from a plugin blob.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SchemaPayload {
    /// Plugin name
    pub name: String,

    /// Plugin version
    pub version: String,

    /// Human-readable description
    pub description: Option<String>,

    /// OSCAL category (software, network, system, security, compliance, observability)
    pub category: Option<String>,

    /// State fields with types and constraints
    pub fields: HashMap<String, FieldSchema>,

    /// Available methods
    pub methods: HashMap<String, MethodSchema>,

    /// OSCAL subids for traceability
    pub subids: HashMap<String, String>,

    /// Raw schema JSON (for tool responses)
    pub raw_json: serde_json::Value,
}

/// Field schema from a plugin.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FieldSchema {
    /// Field type (string, number, boolean, object, array)
    pub field_type: FieldType,

    /// Human-readable description
    pub description: Option<String>,

    /// Default value if not specified
    pub default: Option<serde_json::Value>,

    /// Whether field is required
    pub required: bool,

    /// Whether field is read-only
    pub read_only: bool,

    /// Validation constraints
    pub constraints: Option<Constraints>,

    /// OSCAL subid
    pub subid: Option<String>,
}

/// Field type variants.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum FieldType {
    String,
    Number,
    Integer,
    Boolean,
    Array { items: Box<FieldType> },
    Object { properties: HashMap<String, FieldSchema> },
    Enum { values: Vec<String> },
    OneOf { variants: Vec<FieldType> },
}

/// Validation constraints for a field.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Constraints {
    pub min: Option<f64>,
    pub max: Option<f64>,
    pub pattern: Option<String>,
    pub min_length: Option<usize>,
    pub max_length: Option<usize>,
}

/// Method schema from a plugin.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct MethodSchema {
    /// Human-readable description
    pub description: Option<String>,

    /// Input argument schema
    pub args: Option<serde_json::Value>,

    /// Return value schema
    pub returns: Option<serde_json::Value>,

    /// Side effect classification
    pub side_effect: SideEffect,

    /// Whether method is idempotent
    pub idempotent: bool,

    /// Required capability to invoke
    pub required_capability: Option<String>,

    /// OSCAL subid
    pub subid: Option<String>,
}

/// Method side effect classification.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum SideEffect {
    Read,
    Mutation,
}

impl GenerationContext {
    /// Create a new generation context with baseline data.
    pub fn new(schemas: Vec<SchemaPayload>) -> Self {
        Self {
            schemas,
            access_instructions: include_str!("../../../docs/gallery-gen/access-instructions.md").to_string(),
            catalog_docs: include_str!("../../../docs/gallery-gen/json-render-catalog.md").to_string(),
            grammar_docs: include_str!("../../../docs/gallery-gen/spec-grammar.md").to_string(),
            universal_prompt: "Make this dataset as accessible to as many people, industries, causes as possible.".to_string(),
            operator_guidance: None,
            mcp_enabled: false,
            qdrant_enabled: false,
        }
    }

    /// Build the system message for the inference model.
    pub fn build_system_message(&self) -> String {
        let mut parts = vec![
            "# Gallery Generation System".to_string(),
            "".to_string(),
            "You are a UI specification generator. Your task is to create json-render.dev specifications that make plugin data accessible and useful.".to_string(),
            "".to_string(),
            "## Available Plugins".to_string(),
        ];

        for schema in &self.schemas {
            parts.push(format!("- **{}** ({}): {}", 
                schema.name, 
                schema.version,
                schema.description.as_deref().unwrap_or("No description")
            ));
        }

        parts.push("".to_string());
        parts.push("## Component Catalog".to_string());
        parts.push(self.catalog_docs.clone());
        parts.push("".to_string());
        parts.push("## Spec Grammar".to_string());
        parts.push(self.grammar_docs.clone());
        parts.push("".to_string());
        parts.push("## Plugin Schema Access".to_string());
        parts.push(self.access_instructions.clone());

        parts.join("\n")
    }

    /// Build the user message with universal prompt and operator guidance.
    pub fn build_user_message(&self) -> String {
        let mut msg = self.universal_prompt.clone();

        if let Some(guidance) = &self.operator_guidance {
            msg.push_str("\n\n## Operator Guidance\n");
            msg.push_str(guidance);
        }

        msg
    }
}

impl SchemaPayload {
    /// Parse a schema payload from raw plugin schema JSON.
    pub fn from_raw(name: String, raw: serde_json::Value) -> Result<Self> {
        let version = raw.get("version")
            .and_then(|v| v.as_str())
            .unwrap_or("1.0.0")
            .to_string();

        let description = raw.get("description")
            .and_then(|d| d.as_str())
            .map(|s| s.to_string());

        let category = raw.get("x-oscal-category")
            .and_then(|c| c.as_str())
            .map(|s| s.to_string());

        // Parse fields (simplified for now - full parsing would be recursive)
        let fields = parse_fields(raw.get("fields"))?;

        // Parse methods
        let methods = parse_methods(raw.get("methods"))?;

        // Extract subids
        let subids = raw.get("subids")
            .and_then(|s| s.as_object())
            .map(|obj| {
                obj.iter()
                    .map(|(k, v)| (k.clone(), v.as_str().unwrap_or("").to_string()))
                    .collect()
            })
            .unwrap_or_default();

        Ok(Self {
            name,
            version,
            description,
            category,
            fields,
            methods,
            subids,
            raw_json: raw,
        })
    }
}

fn parse_fields(fields_val: Option<&serde_json::Value>) -> Result<HashMap<String, FieldSchema>> {
    let mut fields = HashMap::new();

    if let Some(obj) = fields_val.and_then(|v| v.as_object()) {
        for (name, field_val) in obj {
            if let Ok(field) = parse_field(field_val) {
                fields.insert(name.clone(), field);
            }
        }
    }

    Ok(fields)
}

fn parse_field(val: &serde_json::Value) -> Result<FieldSchema> {
    let field_type = parse_field_type(val.get("field_type"))?;

    let description = val.get("description")
        .and_then(|d| d.as_str())
        .map(|s| s.to_string());

    let default = val.get("default").cloned();
    let required = val.get("required").and_then(|r| r.as_bool()).unwrap_or(false);
    let read_only = val.get("read_only").and_then(|r| r.as_bool()).unwrap_or(false);

    let constraints = val.get("constraints").map(|c| parse_constraints(c));

    let subid = val.get("subid")
        .and_then(|s| s.as_str())
        .map(|s| s.to_string());

    Ok(FieldSchema {
        field_type,
        description,
        default,
        required,
        read_only,
        constraints,
        subid,
    })
}

fn parse_field_type(val: Option<&serde_json::Value>) -> Result<FieldType> {
    match val {
        Some(serde_json::Value::String(s)) => {
            match s.as_str() {
                "string" => Ok(FieldType::String),
                "number" => Ok(FieldType::Number),
                "integer" => Ok(FieldType::Integer),
                "boolean" => Ok(FieldType::Boolean),
                _ => Ok(FieldType::String), // Default fallback
            }
        }
        Some(serde_json::Value::Object(obj)) => {
            if let Some(items) = obj.get("array") {
                let item_type = parse_field_type(Some(items))?;
                Ok(FieldType::Array { items: Box::new(item_type) })
            } else if let Some(props) = obj.get("object") {
                let properties = parse_fields(Some(props))?;
                Ok(FieldType::Object { properties })
            } else if let Some(vals) = obj.get("enumValues") {
                let values = vals.as_array()
                    .map(|arr| arr.iter().filter_map(|v| v.as_str().map(|s| s.to_string())).collect())
                    .unwrap_or_default();
                Ok(FieldType::Enum { values })
            } else {
                Ok(FieldType::String)
            }
        }
        _ => Ok(FieldType::String),
    }
}

fn parse_constraints(val: &serde_json::Value) -> Constraints {
    Constraints {
        min: val.get("min").and_then(|v| v.as_f64()),
        max: val.get("max").and_then(|v| v.as_f64()),
        pattern: val.get("pattern").and_then(|v| v.as_str().map(|s| s.to_string())),
        min_length: val.get("minLength").and_then(|v| v.as_u64().map(|n| n as usize)),
        max_length: val.get("maxLength").and_then(|v| v.as_u64().map(|n| n as usize)),
    }
}

fn parse_methods(methods_val: Option<&serde_json::Value>) -> Result<HashMap<String, MethodSchema>> {
    let mut methods = HashMap::new();

    if let Some(obj) = methods_val.and_then(|v| v.as_object()) {
        for (name, method_val) in obj {
            if let Ok(method) = parse_method(method_val) {
                methods.insert(name.clone(), method);
            }
        }
    }

    Ok(methods)
}

fn parse_method(val: &serde_json::Value) -> Result<MethodSchema> {
    let description = val.get("description")
        .and_then(|d| d.as_str())
        .map(|s| s.to_string());

    let args = val.get("args").cloned();
    let returns = val.get("returns").cloned();

    let side_effect = val.get("side_effect")
        .and_then(|s| s.as_str())
        .map(|s| match s {
            "mutation" => SideEffect::Mutation,
            _ => SideEffect::Read,
        })
        .unwrap_or(SideEffect::Read);

    let idempotent = val.get("idempotent")
        .and_then(|i| i.as_bool())
        .unwrap_or(false);

    let required_capability = val.get("required_capability")
        .and_then(|c| c.as_str())
        .map(|s| s.to_string());

    let subid = val.get("subid")
        .and_then(|s| s.as_str())
        .map(|s| s.to_string());

    Ok(MethodSchema {
        description,
        args,
        returns,
        side_effect,
        idempotent,
        required_capability,
        subid,
    })
}

//! Inference loop for gallery generation.
//!
//! Calls ZeroClaw `/v1/chat/completions` with tool support for:
//! - Plugin schema queries
//! - MCP cross-blob discovery (when enabled)
//! - Qdrant semantic search (when enabled)

use anyhow::{Result, Context};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;

use crate::context::GenerationContext;
use crate::tools::{ToolRegistry, ToolCall, ToolResult};

/// Inference loop that generates UI specs.
pub struct InferenceLoop {
    /// ZeroClaw HTTP client
    client: reqwest::Client,

    /// ZeroClaw endpoint
    endpoint: String,

    /// Maximum turns per spec
    max_turns: usize,

    /// Tool registry
    tools: ToolRegistry,
}

/// OpenAI-compatible chat message.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ChatMessage {
    pub role: String,
    pub content: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tool_calls: Option<Vec<ToolCall>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tool_call_id: Option<String>,
}

/// OpenAI-compatible chat completion request.
#[derive(Debug, Clone, Serialize)]
pub struct ChatRequest {
    pub model: String,
    pub messages: Vec<ChatMessage>,
    pub tools: Option<Vec<ToolDefinition>>,
    pub stream: bool,
}

/// OpenAI-compatible tool definition.
#[derive(Debug, Clone, Serialize)]
pub struct ToolDefinition {
    #[serde(rename = "type")]
    pub tool_type: String,
    pub function: FunctionDefinition,
}

/// OpenAI-compatible function definition.
#[derive(Debug, Clone, Serialize)]
pub struct FunctionDefinition {
    pub name: String,
    pub description: String,
    pub parameters: serde_json::Value,
}

/// OpenAI-compatible chat completion response.
#[derive(Debug, Clone, Deserialize)]
pub struct ChatResponse {
    pub id: String,
    pub choices: Vec<Choice>,
}

/// Response choice.
#[derive(Debug, Clone, Deserialize)]
pub struct Choice {
    pub index: u32,
    pub message: ChatMessage,
    pub finish_reason: String,
}

/// Generated spec result.
#[derive(Debug, Clone)]
pub struct GeneratedSpec {
    /// The spec JSON
    pub spec: serde_json::Value,

    /// Plugin targeted
    pub target_plugin: Option<String>,

    /// Generation metadata
    pub metadata: HashMap<String, String>,
}

impl InferenceLoop {
    /// Create a new inference loop.
    pub fn new(endpoint: String, max_turns: usize) -> Self {
        Self {
            client: reqwest::Client::new(),
            endpoint,
            max_turns,
            tools: ToolRegistry::new(),
        }
    }

    /// Run a generation session.
    pub async fn generate(&self, ctx: &GenerationContext) -> Result<GeneratedSpec> {
        // Build initial messages
        let mut messages = vec![
            ChatMessage {
                role: "system".to_string(),
                content: Some(ctx.build_system_message()),
                tool_calls: None,
                tool_call_id: None,
            },
            ChatMessage {
                role: "user".to_string(),
                content: Some(ctx.build_user_message()),
                tool_calls: None,
                tool_call_id: None,
            },
        ];

        // Build tool definitions
        let tool_defs = self.build_tool_definitions(ctx);

        // Inference loop
        for turn in 0..self.max_turns {
            tracing::info!("Inference turn {} of {}", turn + 1, self.max_turns);

            // Call ZeroClaw
            let response = self.call_zeroclaw(&messages, &tool_defs).await
                .context("ZeroClaw inference call failed")?;

            // Extract assistant message
            let assistant_msg = response.choices.first()
                .map(|c| c.message.clone())
                .context("No response from model")?;

            // Check for tool calls
            if let Some(tool_calls) = &assistant_msg.tool_calls {
                // Add assistant message to history
                messages.push(assistant_msg.clone());

                // Execute tool calls
                for tool_call in tool_calls {
                    let result = self.tools.execute(tool_call, ctx).await;

                    // Add tool result to messages
                    messages.push(ChatMessage {
                        role: "tool".to_string(),
                        content: Some(serde_json::to_string(&result)?),
                        tool_calls: None,
                        tool_call_id: Some(tool_call.id.clone()),
                    });
                }
            } else {
                // No tool calls - check if we have a spec
                if let Some(content) = &assistant_msg.content {
                    if let Ok(spec) = self.extract_spec(content) {
                        tracing::info!("Successfully extracted spec on turn {}", turn + 1);
                        return Ok(GeneratedSpec {
                            spec,
                            target_plugin: None,
                            metadata: HashMap::new(),
                        });
                    }
                }

                // Add to history and continue
                messages.push(assistant_msg);
            }
        }

        anyhow::bail!("Max turns reached without generating a valid spec")
    }

    /// Call ZeroClaw chat completions endpoint.
    async fn call_zeroclaw(
        &self,
        messages: &[ChatMessage],
        tools: &[ToolDefinition],
    ) -> Result<ChatResponse> {
        let url = format!("{}/v1/chat/completions", self.endpoint);

        let request = ChatRequest {
            model: "default".to_string(), // ZeroClaw selects the actual model
            messages: messages.to_vec(),
            tools: if tools.is_empty() { None } else { Some(tools.to_vec()) },
            stream: false,
        };

        let response = self.client
            .post(&url)
            .json(&request)
            .send()
            .await
            .context("HTTP request failed")?;

        if !response.status().is_success() {
            let status = response.status();
            let body = response.text().await.unwrap_or_default();
            anyhow::bail!("ZeroClaw returned {}: {}", status, body);
        }

        response.json().await.context("Failed to parse response")
    }

    /// Build tool definitions based on enabled features.
    fn build_tool_definitions(&self, ctx: &GenerationContext) -> Vec<ToolDefinition> {
        let mut tools = vec![
            // Always available: list plugins
            ToolDefinition {
                tool_type: "function".to_string(),
                function: FunctionDefinition {
                    name: "list_plugins".to_string(),
                    description: "List all available plugins with their names and categories".to_string(),
                    parameters: serde_json::json!({
                        "type": "object",
                        "properties": {}
                    }),
                },
            },
            // Always available: get plugin schema
            ToolDefinition {
                tool_type: "function".to_string(),
                function: FunctionDefinition {
                    name: "get_plugin_schema".to_string(),
                    description: "Get the full schema for a specific plugin".to_string(),
                    parameters: serde_json::json!({
                        "type": "object",
                        "properties": {
                            "plugin_name": {
                                "type": "string",
                                "description": "Name of the plugin to get schema for"
                            }
                        },
                        "required": ["plugin_name"]
                    }),
                },
            },
            // Always available: search fields
            ToolDefinition {
                tool_type: "function".to_string(),
                function: FunctionDefinition {
                    name: "search_fields".to_string(),
                    description: "Search for fields across all plugins by name pattern".to_string(),
                    parameters: serde_json::json!({
                        "type": "object",
                        "properties": {
                            "pattern": {
                                "type": "string",
                                "description": "Pattern to search for in field names"
                            }
                        },
                        "required": ["pattern"]
                    }),
                },
            },
        ];

        // MCP-specific tools
        if ctx.mcp_enabled {
            tools.push(ToolDefinition {
                tool_type: "function".to_string(),
                function: FunctionDefinition {
                    name: "search_methods".to_string(),
                    description: "Search for methods across all plugins by name pattern".to_string(),
                    parameters: serde_json::json!({
                        "type": "object",
                        "properties": {
                            "pattern": {
                                "type": "string",
                                "description": "Pattern to search for in method names"
                            }
                        },
                        "required": ["pattern"]
                    }),
                },
            });

            tools.push(ToolDefinition {
                tool_type: "function".to_string(),
                function: FunctionDefinition {
                    name: "search_subids".to_string(),
                    description: "Search for OSCAL subids by category or pattern".to_string(),
                    parameters: serde_json::json!({
                        "type": "object",
                        "properties": {
                            "category": {
                                "type": "string",
                                "description": "OSCAL category to filter by (src, prj, sch, mut, obs, evt, exp)"
                            },
                            "pattern": {
                                "type": "string",
                                "description": "Pattern to search for in subids"
                            }
                        }
                    }),
                },
            });

            tools.push(ToolDefinition {
                tool_type: "function".to_string(),
                function: FunctionDefinition {
                    name: "find_related".to_string(),
                    description: "Find plugins related to a given plugin by shared fields or methods".to_string(),
                    parameters: serde_json::json!({
                        "type": "object",
                        "properties": {
                            "plugin_name": {
                                "type": "string",
                                "description": "Plugin to find relations for"
                            }
                        },
                        "required": ["plugin_name"]
                    }),
                },
            });
        }

        // Qdrant-specific tools
        if ctx.qdrant_enabled {
            tools.push(ToolDefinition {
                tool_type: "function".to_string(),
                function: FunctionDefinition {
                    name: "semantic_search".to_string(),
                    description: "Semantic search across all plugin schemas using vector embeddings".to_string(),
                    parameters: serde_json::json!({
                        "type": "object",
                        "properties": {
                            "query": {
                                "type": "string",
                                "description": "Natural language query to search for"
                            },
                            "limit": {
                                "type": "integer",
                                "description": "Maximum results to return",
                                "default": 10
                            }
                        },
                        "required": ["query"]
                    }),
                },
            });
        }

        tools
    }

    /// Extract a spec from model output.
    fn extract_spec(&self, content: &str) -> Result<serde_json::Value> {
        // Try to parse as direct JSON
        if let Ok(spec) = serde_json::from_str::<serde_json::Value>(content) {
            if spec.get("root").is_some() && spec.get("elements").is_some() {
                return Ok(spec);
            }
        }

        // Try to extract from markdown code block
        if let Some(json_start) = content.find("```json") {
            let json_start = json_start + 7;
            if let Some(json_end) = content[json_start..].find("```") {
                let json_str = &content[json_start..json_start + json_end].trim();
                if let Ok(spec) = serde_json::from_str::<serde_json::Value>(json_str) {
                    if spec.get("root").is_some() && spec.get("elements").is_some() {
                        return Ok(spec);
                    }
                }
            }
        }

        // Try to extract from generic code block
        if let Some(code_start) = content.find("```") {
            let code_start = code_start + 3;
            // Skip language identifier if present
            let code_start = if let Some(newline_pos) = content[code_start..].find('\n') {
                code_start + newline_pos + 1
            } else {
                code_start
            };

            if let Some(code_end) = content[code_start..].find("```") {
                let code_str = &content[code_start..code_start + code_end].trim();
                if let Ok(spec) = serde_json::from_str::<serde_json::Value>(code_str) {
                    if spec.get("root").is_some() && spec.get("elements").is_some() {
                        return Ok(spec);
                    }
                }
            }
        }

        anyhow::bail!("No valid spec found in model output")
    }
}

//! Tool execution layer for inference loop.
//!
//! Provides tools for:
//! - Plugin schema queries (always available)
//! - MCP cross-blob discovery (when enabled)
//! - Qdrant semantic search (when enabled)

use anyhow::Result;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;

use crate::context::{GenerationContext, SchemaPayload};

/// Registry of available tools.
pub struct ToolRegistry {
    // Future: Qdrant client when enabled
}

/// OpenAI-compatible tool call.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolCall {
    pub id: String,
    #[serde(rename = "type")]
    pub call_type: String,
    pub function: FunctionCall,
}

/// Function call within a tool call.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FunctionCall {
    pub name: String,
    pub arguments: String,
}

/// Tool execution result.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolResult {
    pub success: bool,
    pub result: serde_json::Value,
}

impl ToolRegistry {
    /// Create a new tool registry.
    pub fn new() -> Self {
        Self {}
    }

    /// Execute a tool call.
    pub async fn execute(&self, call: &ToolCall, ctx: &GenerationContext) -> ToolResult {
        let args: HashMap<String, serde_json::Value> = 
            serde_json::from_str(&call.function.arguments).unwrap_or_default();

        match call.function.name.as_str() {
            "list_plugins" => self.list_plugins(ctx),
            "get_plugin_schema" => self.get_plugin_schema(ctx, &args),
            "search_fields" => self.search_fields(ctx, &args),
            "search_methods" => self.search_methods(ctx, &args),
            "search_subids" => self.search_subids(ctx, &args),
            "find_related" => self.find_related(ctx, &args),
            "semantic_search" => self.semantic_search(ctx, &args).await,
            _ => ToolResult {
                success: false,
                result: serde_json::json!({
                    "error": format!("Unknown tool: {}", call.function.name)
                }),
            },
        }
    }

    /// List all available plugins.
    fn list_plugins(&self, ctx: &GenerationContext) -> ToolResult {
        let plugins: Vec<serde_json::Value> = ctx.schemas
            .iter()
            .map(|s| serde_json::json!({
                "name": s.name,
                "version": s.version,
                "description": s.description,
                "category": s.category
            }))
            .collect();

        ToolResult {
            success: true,
            result: serde_json::json!({
                "plugins": plugins,
                "count": plugins.len()
            }),
        }
    }

    /// Get the full schema for a specific plugin.
    fn get_plugin_schema(
        &self,
        ctx: &GenerationContext,
        args: &HashMap<String, serde_json::Value>,
    ) -> ToolResult {
        let plugin_name = match args.get("plugin_name").and_then(|v| v.as_str()) {
            Some(name) => name,
            None => return ToolResult {
                success: false,
                result: serde_json::json!({ "error": "Missing plugin_name parameter" }),
            },
        };

        match ctx.schemas.iter().find(|s| s.name == plugin_name) {
            Some(schema) => ToolResult {
                success: true,
                result: schema.raw_json.clone(),
            },
            None => ToolResult {
                success: false,
                result: serde_json::json!({
                    "error": format!("Plugin not found: {}", plugin_name)
                }),
            },
        }
    }

    /// Search for fields across all plugins by name pattern.
    fn search_fields(
        &self,
        ctx: &GenerationContext,
        args: &HashMap<String, serde_json::Value>,
    ) -> ToolResult {
        let pattern = match args.get("pattern").and_then(|v| v.as_str()) {
            Some(p) => p.to_lowercase(),
            None => return ToolResult {
                success: false,
                result: serde_json::json!({ "error": "Missing pattern parameter" }),
            },
        };

        let mut results = Vec::new();

        for schema in &ctx.schemas {
            for (field_name, field) in &schema.fields {
                if field_name.to_lowercase().contains(&pattern) {
                    results.push(serde_json::json!({
                        "plugin": schema.name,
                        "field": field_name,
                        "type": format!("{:?}", field.field_type),
                        "description": field.description
                    }));
                }
            }
        }

        ToolResult {
            success: true,
            result: serde_json::json!({
                "matches": results,
                "count": results.len()
            }),
        }
    }

    /// Search for methods across all plugins (MCP tool).
    fn search_methods(
        &self,
        ctx: &GenerationContext,
        args: &HashMap<String, serde_json::Value>,
    ) -> ToolResult {
        let pattern = match args.get("pattern").and_then(|v| v.as_str()) {
            Some(p) => p.to_lowercase(),
            None => return ToolResult {
                success: false,
                result: serde_json::json!({ "error": "Missing pattern parameter" }),
            },
        };

        let mut results = Vec::new();

        for schema in &ctx.schemas {
            for (method_name, method) in &schema.methods {
                if method_name.to_lowercase().contains(&pattern) {
                    results.push(serde_json::json!({
                        "plugin": schema.name,
                        "method": method_name,
                        "description": method.description,
                        "side_effect": format!("{:?}", method.side_effect)
                    }));
                }
            }
        }

        ToolResult {
            success: true,
            result: serde_json::json!({
                "matches": results,
                "count": results.len()
            }),
        }
    }

    /// Search for OSCAL subids (MCP tool).
    fn search_subids(
        &self,
        ctx: &GenerationContext,
        args: &HashMap<String, serde_json::Value>,
    ) -> ToolResult {
        let category = args.get("category").and_then(|v| v.as_str());
        let pattern = args.get("pattern").and_then(|v| v.as_str());

        let mut results = Vec::new();

        for schema in &ctx.schemas {
            for (subid, description) in &schema.subids {
                let matches_category = category.map_or(true, |c| subid.starts_with(&format!("{}.", c)));
                let matches_pattern = pattern.map_or(true, |p| subid.to_lowercase().contains(&p.to_lowercase()));

                if matches_category && matches_pattern {
                    results.push(serde_json::json!({
                        "plugin": schema.name,
                        "subid": subid,
                        "description": description
                    }));
                }
            }
        }

        ToolResult {
            success: true,
            result: serde_json::json!({
                "matches": results,
                "count": results.len()
            }),
        }
    }

    /// Find plugins related to a given plugin (MCP tool).
    fn find_related(
        &self,
        ctx: &GenerationContext,
        args: &HashMap<String, serde_json::Value>,
    ) -> ToolResult {
        let plugin_name = match args.get("plugin_name").and_then(|v| v.as_str()) {
            Some(name) => name,
            None => return ToolResult {
                success: false,
                result: serde_json::json!({ "error": "Missing plugin_name parameter" }),
            },
        };

        let target_schema = match ctx.schemas.iter().find(|s| s.name == plugin_name) {
            Some(s) => s,
            None => return ToolResult {
                success: false,
                result: serde_json::json!({ "error": format!("Plugin not found: {}", plugin_name) }),
            },
        };

        let target_fields: std::collections::HashSet<_> = target_schema.fields.keys().cloned().collect();
        let target_methods: std::collections::HashSet<_> = target_schema.methods.keys().cloned().collect();

        let mut related = Vec::new();

        for schema in &ctx.schemas {
            if schema.name == plugin_name {
                continue;
            }

            let shared_fields: Vec<_> = schema.fields.keys()
                .filter(|f| target_fields.contains(*f))
                .cloned()
                .collect();

            let shared_methods: Vec<_> = schema.methods.keys()
                .filter(|m| target_methods.contains(*m))
                .cloned()
                .collect();

            if !shared_fields.is_empty() || !shared_methods.is_empty() {
                related.push(serde_json::json!({
                    "plugin": schema.name,
                    "shared_fields": shared_fields,
                    "shared_methods": shared_methods
                }));
            }
        }

        ToolResult {
            success: true,
            result: serde_json::json!({
                "target": plugin_name,
                "related": related,
                "count": related.len()
            }),
        }
    }

    /// Semantic search using Qdrant (Qdrant tool).
    async fn semantic_search(
        &self,
        ctx: &GenerationContext,
        args: &HashMap<String, serde_json::Value>,
    ) -> ToolResult {
        let query = match args.get("query").and_then(|v| v.as_str()) {
            Some(q) => q,
            None => return ToolResult {
                success: false,
                result: serde_json::json!({ "error": "Missing query parameter" }),
            },
        };

        let limit = args.get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(10) as usize;

        // TODO: Implement actual Qdrant integration
        // For now, do simple keyword matching as fallback
        let query_lower = query.to_lowercase();
        let mut results = Vec::new();

        for schema in &ctx.schemas {
            let mut score = 0.0;

            // Check name match
            if schema.name.to_lowercase().contains(&query_lower) {
                score += 0.5;
            }

            // Check description match
            if let Some(desc) = &schema.description {
                if desc.to_lowercase().contains(&query_lower) {
                    score += 0.3;
                }
            }

            // Check field names
            for field_name in schema.fields.keys() {
                if field_name.to_lowercase().contains(&query_lower) {
                    score += 0.1;
                }
            }

            if score > 0.0 {
                results.push(serde_json::json!({
                    "plugin": schema.name,
                    "score": score,
                    "description": schema.description
                }));
            }
        }

        results.sort_by(|a, b| {
            let score_a = a.get("score").and_then(|s| s.as_f64()).unwrap_or(0.0);
            let score_b = b.get("score").and_then(|s| s.as_f64()).unwrap_or(0.0);
            score_b.partial_cmp(&score_a).unwrap_or(std::cmp::Ordering::Equal)
        });

        results.truncate(limit);

        ToolResult {
            success: true,
            result: serde_json::json!({
                "query": query,
                "results": results,
                "note": "Using keyword matching (Qdrant not yet integrated)"
            }),
        }
    }
}

impl Default for ToolRegistry {
    fn default() -> Self {
        Self::new()
    }
}

//! Spec validator for gallery admission.
//!
//! Validates generated specs against the json-render.dev grammar:
//! - Structure checks (root, elements, references)
//! - Type checks (known components)
//! - Prop schema validation
//! - Children validation
//! - Bind path validation
//! - Cycle detection
//! - Signature deduplication

use anyhow::{Result, Context};
use serde::{Deserialize, Serialize};
use std::collections::{HashMap, HashSet};

/// Spec validation result.
#[derive(Debug, Clone)]
pub struct ValidationResult {
    /// Whether the spec is valid
    pub valid: bool,

    /// Validation errors (if any)
    pub errors: Vec<ValidationError>,

    /// Spec signature for deduplication
    pub signature: String,
}

/// Validation error.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ValidationError {
    pub code: String,
    pub message: String,
}

/// Spec validator.
pub struct SpecValidator {
    /// Known component types
    stable_core: HashSet<&'static str>,
}

impl SpecValidator {
    /// Create a new spec validator.
    pub fn new() -> Self {
        Self {
            stable_core: [
                // Layout
                "stack", "card", "separator", "space",
                // Text
                "heading", "label", "muted",
                // Status
                "status_pill",
                // Action
                "button", "button_group",
                // Data Display
                "kv_pair", "table", "log_stream", "flow_table", "metric_card",
                // Form
                "text_input", "number_input", "select", "toggle",
                // Dynamic
                "repeat", "schema_form",
            ].iter().cloned().collect(),
        }
    }

    /// Validate a spec.
    pub fn validate(&self, spec: &serde_json::Value) -> ValidationResult {
        let mut errors = Vec::new();

        // 1. Structure check
        let root_id = match self.check_structure(spec) {
            Ok(id) => id,
            Err(e) => {
                errors.push(e);
                return ValidationResult {
                    valid: false,
                    errors,
                    signature: String::new(),
                };
            }
        };

        let elements = match spec.get("elements").and_then(|e| e.as_object()) {
            Some(obj) => obj,
            None => {
                errors.push(ValidationError {
                    code: "E_MISSING_ELEMENTS".to_string(),
                    message: "Spec missing 'elements' object".to_string(),
                });
                return ValidationResult {
                    valid: false,
                    errors,
                    signature: String::new(),
                };
            }
        };

        // 2. Reference check
        if let Err(e) = self.check_references(root_id, elements) {
            errors.push(e);
        }

        // 3. Type check
        for (id, element) in elements {
            if let Err(e) = self.check_type(id, element) {
                errors.push(e);
            }
        }

        // 4. Prop schema check
        for (id, element) in elements {
            if let Err(e) = self.check_props(id, element) {
                errors.push(e);
            }
        }

        // 5. Children check
        for (id, element) in elements {
            if let Err(e) = self.check_children(id, element, elements) {
                errors.push(e);
            }
        }

        // 6. Bind path check
        for (id, element) in elements {
            if let Err(e) = self.check_bind_paths(id, element) {
                errors.push(e);
            }
        }

        // 7. Cycle check
        if let Err(e) = self.check_cycles(root_id, elements) {
            errors.push(e);
        }

        // 8. Generate signature
        let signature = self.compute_signature(spec);

        ValidationResult {
            valid: errors.is_empty(),
            errors,
            signature,
        }
    }

    /// Check top-level structure.
    fn check_structure(&self, spec: &serde_json::Value) -> Result<String, ValidationError> {
        if !spec.is_object() {
            return Err(ValidationError {
                code: "E_INVALID_SPEC".to_string(),
                message: "Spec must be a JSON object".to_string(),
            });
        }

        let root_id = spec.get("root")
            .and_then(|r| r.as_str())
            .ok_or_else(|| ValidationError {
                code: "E_MISSING_ROOT".to_string(),
                message: "Spec missing 'root' field".to_string(),
            })?
            .to_string();

        if !spec.get("elements").map_or(false, |e| e.is_object()) {
            return Err(ValidationError {
                code: "E_MISSING_ELEMENTS".to_string(),
                message: "Spec missing 'elements' object".to_string(),
            });
        }

        Ok(root_id)
    }

    /// Check that all element references exist.
    fn check_references(
        &self,
        root_id: String,
        elements: &serde_json::Map<String, serde_json::Value>,
    ) -> Result<(), ValidationError> {
        // Check root exists
        if !elements.contains_key(&root_id) {
            return Err(ValidationError {
                code: "E_MISSING_ROOT".to_string(),
                message: format!("Root element '{}' not found in elements", root_id),
            });
        }

        // Check all children references
        for (id, element) in elements {
            if let Some(children) = element.get("children").and_then(|c| c.as_array()) {
                for child_id in children {
                    if let Some(child_str) = child_id.as_str() {
                        if !elements.contains_key(child_str) {
                            return Err(ValidationError {
                                code: "E_DANGLING_REF".to_string(),
                                message: format!(
                                    "Element '{}' references non-existent child '{}'",
                                    id, child_str
                                ),
                            });
                        }
                    }
                }
            }
        }

        Ok(())
    }

    /// Check that element type is known.
    fn check_type(&self, id: &str, element: &serde_json::Value) -> Result<(), ValidationError> {
        let type_name = element.get("type")
            .and_then(|t| t.as_str())
            .ok_or_else(|| ValidationError {
                code: "E_MISSING_TYPE".to_string(),
                message: format!("Element '{}' missing 'type' field", id),
            })?;

        if !self.stable_core.contains(type_name) {
            // Allow novelty types with a warning (not an error)
            tracing::warn!("Element '{}' uses novelty type: {}", id, type_name);
        }

        Ok(())
    }

    /// Check props against component schemas.
    fn check_props(&self, id: &str, element: &serde_json::Value) -> Result<(), ValidationError> {
        let type_name = element.get("type")
            .and_then(|t| t.as_str())
            .unwrap_or("");

        let props = element.get("props").and_then(|p| p.as_object());

        match type_name {
            "heading" => {
                if let Some(p) = props {
                    if !p.contains_key("text") && !p.contains_key("bind") {
                        return Err(ValidationError {
                            code: "E_PROP_SCHEMA".to_string(),
                            message: format!("Element '{}' (heading) requires 'text' or 'bind' prop", id),
                        });
                    }
                }
            }
            "label" => {
                if let Some(p) = props {
                    if !p.contains_key("text") && !p.contains_key("bind") {
                        return Err(ValidationError {
                            code: "E_PROP_SCHEMA".to_string(),
                            message: format!("Element '{}' (label) requires 'text' or 'bind' prop", id),
                        });
                    }
                }
            }
            "status_pill" => {
                if let Some(p) = props {
                    if !p.contains_key("bind") {
                        return Err(ValidationError {
                            code: "E_PROP_SCHEMA".to_string(),
                            message: format!("Element '{}' (status_pill) requires 'bind' prop", id),
                        });
                    }
                }
            }
            "button" => {
                if let Some(p) = props {
                    if !p.contains_key("label") {
                        return Err(ValidationError {
                            code: "E_PROP_SCHEMA".to_string(),
                            message: format!("Element '{}' (button) requires 'label' prop", id),
                        });
                    }
                }
            }
            "table" => {
                if let Some(p) = props {
                    if !p.contains_key("bind") {
                        return Err(ValidationError {
                            code: "E_PROP_SCHEMA".to_string(),
                            message: format!("Element '{}' (table) requires 'bind' prop", id),
                        });
                    }
                    if !p.contains_key("columns") {
                        return Err(ValidationError {
                            code: "E_PROP_SCHEMA".to_string(),
                            message: format!("Element '{}' (table) requires 'columns' prop", id),
                        });
                    }
                }
            }
            _ => {}
        }

        Ok(())
    }

    /// Check children are valid for each component.
    fn check_children(
        &self,
        id: &str,
        element: &serde_json::Value,
        elements: &serde_json::Map<String, serde_json::Value>,
    ) -> Result<(), ValidationError> {
        let type_name = element.get("type")
            .and_then(|t| t.as_str())
            .unwrap_or("");

        let children = element.get("children").and_then(|c| c.as_array());

        // Components that don't accept children
        let no_children = [
            "heading", "label", "muted", "status_pill", "button",
            "separator", "space", "kv_pair", "table", "log_stream",
            "flow_table", "metric_card", "text_input", "number_input",
            "select", "toggle",
        ];

        if no_children.contains(&type_name) && children.is_some() {
            return Err(ValidationError {
                code: "E_CHILDREN_NOT_ALLOWED".to_string(),
                message: format!("Component '{}' does not accept children", type_name),
            });
        }

        // Components that require children
        let requires_children = ["stack", "card"];

        if requires_children.contains(&type_name) {
            match children {
                Some(arr) if arr.is_empty() => {
                    return Err(ValidationError {
                        code: "E_CHILDREN_REQUIRED".to_string(),
                        message: format!("Component '{}' requires non-empty children", type_name),
                    });
                }
                None => {
                    return Err(ValidationError {
                        code: "E_CHILDREN_REQUIRED".to_string(),
                        message: format!("Component '{}' requires children", type_name),
                    });
                }
                _ => {}
            }
        }

        Ok(())
    }

    /// Check bind paths start with '/'.
    fn check_bind_paths(&self, id: &str, element: &serde_json::Value) -> Result<(), ValidationError> {
        if let Some(props) = element.get("props").and_then(|p| p.as_object()) {
            if let Some(bind) = props.get("bind").and_then(|b| b.as_str()) {
                if !bind.starts_with('/') {
                    return Err(ValidationError {
                        code: "E_BIND_PATH".to_string(),
                        message: format!(
                            "Invalid bind path '{}' in element '{}' (must start with '/')",
                            bind, id
                        ),
                    });
                }
            }
        }

        Ok(())
    }

    /// Check for cycles in element tree.
    fn check_cycles(
        &self,
        root_id: &str,
        elements: &serde_json::Map<String, serde_json::Value>,
    ) -> Result<(), ValidationError> {
        let mut visited = HashSet::new();
        let mut path = Vec::new();

        self.detect_cycle(root_id, elements, &mut visited, &mut path)
    }

    /// Recursive cycle detection.
    fn detect_cycle(
        &self,
        current_id: &str,
        elements: &serde_json::Map<String, serde_json::Value>,
        visited: &mut HashSet<String>,
        path: &mut Vec<String>,
    ) -> Result<(), ValidationError> {
        if path.contains(&current_id.to_string()) {
            let cycle_path = path.join(" -> ");
            return Err(ValidationError {
                code: "E_CYCLE".to_string(),
                message: format!("Cycle detected: {} -> {}", cycle_path, current_id),
            });
        }

        if visited.contains(current_id) {
            return Ok(());
        }

        visited.insert(current_id.to_string());
        path.push(current_id.to_string());

        if let Some(element) = elements.get(current_id) {
            if let Some(children) = element.get("children").and_then(|c| c.as_array()) {
                for child_id in children {
                    if let Some(child_str) = child_id.as_str() {
                        self.detect_cycle(child_str, elements, visited, path)?;
                    }
                }
            }
        }

        path.pop();
        Ok(())
    }

    /// Compute signature for deduplication.
    fn compute_signature(&self, spec: &serde_json::Value) -> String {
        use sha2::{Sha256, Digest};

        // Normalize spec by sorting keys
        let normalized = self.normalize_json(spec);
        let json_str = serde_json::to_string(&normalized).unwrap_or_default();

        let mut hasher = Sha256::new();
        hasher.update(json_str.as_bytes());
        let hash = hasher.finalize();

        hex::encode(hash)
    }

    /// Normalize JSON for consistent hashing.
    fn normalize_json(&self, value: &serde_json::Value) -> serde_json::Value {
        match value {
            serde_json::Value::Object(obj) => {
                let mut sorted: serde_json::Map<String, serde_json::Value> = serde_json::Map::new();
                let mut keys: Vec<_> = obj.keys().collect();
                keys.sort();

                for key in keys {
                    sorted.insert(key.clone(), self.normalize_json(&obj[key]));
                }

                serde_json::Value::Object(sorted)
            }
            serde_json::Value::Array(arr) => {
                serde_json::Value::Array(arr.iter().map(|v| self.normalize_json(v)).collect())
            }
            _ => value.clone(),
        }
    }
}

impl Default for SpecValidator {
    fn default() -> Self {
        Self::new()
    }
}

//! Gallery admission for validated specs.
//!
//! Admits validated specs to the catalog store:
//! - Signature deduplication
//! - Stable-core protection
//! - Gallery size management (200 slots)
//! - Immutable versioning

use anyhow::{Result, Context};
use serde::{Deserialize, Serialize};
use std::collections::HashSet;

use crate::validator::ValidationResult;

/// Gallery admission controller.
pub struct GalleryAdmission {
    /// Maximum gallery size (default: 200)
    max_size: usize,

    /// Maximum stable-core elements to protect (default: 40)
    stable_core_max: usize,

    /// Existing signatures for deduplication
    existing_signatures: HashSet<String>,
}

/// Admission result.
#[derive(Debug, Clone)]
pub struct AdmissionResult {
    /// Whether the spec was admitted
    pub admitted: bool,

    /// Reason for rejection (if not admitted)
    pub rejection_reason: Option<String>,

    /// Slot number assigned (if admitted)
    pub slot: Option<usize>,
}

impl GalleryAdmission {
    /// Create a new gallery admission controller.
    pub fn new(max_size: usize, stable_core_max: usize) -> Self {
        Self {
            max_size,
            stable_core_max,
            existing_signatures: HashSet::new(),
        }
    }

    /// Load existing signatures from catalog store.
    pub fn load_existing_signatures(&mut self, signatures: HashSet<String>) {
        self.existing_signatures = signatures;
    }

    /// Attempt to admit a validated spec to the gallery.
    pub fn admit(&self, validation: &ValidationResult) -> AdmissionResult {
        // Check validation
        if !validation.valid {
            return AdmissionResult {
                admitted: false,
                rejection_reason: Some("Spec failed validation".to_string()),
                slot: None,
            };
        }

        // Check signature deduplication
        if self.existing_signatures.contains(&validation.signature) {
            return AdmissionResult {
                admitted: false,
                rejection_reason: Some("Spec signature already exists in gallery".to_string()),
                slot: None,
            };
        }

        // TODO: Check stable-core protection
        // TODO: Find available slot
        // TODO: Admit to catalog store

        AdmissionResult {
            admitted: true,
            rejection_reason: None,
            slot: Some(0), // Placeholder
        }
    }

    /// Find the next available slot in the gallery.
    pub fn find_available_slot(&self) -> Option<usize> {
        // TODO: Query catalog store for available slots
        // For now, return a placeholder
        Some(0)
    }

    /// Check if a slot is in the stable-core protected range.
    pub fn is_stable_core_slot(&self, slot: usize) -> bool {
        slot < self.stable_core_max
    }

    /// Get gallery statistics.
    pub fn stats(&self) -> GalleryStats {
        GalleryStats {
            max_size: self.max_size,
            stable_core_max: self.stable_core_max,
            current_size: self.existing_signatures.len(),
            available_slots: self.max_size.saturating_sub(self.existing_signatures.len()),
        }
    }
}

/// Gallery statistics.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GalleryStats {
    pub max_size: usize,
    pub stable_core_max: usize,
    pub current_size: usize,
    pub available_slots: usize,
}

impl Default for GalleryAdmission {
    fn default() -> Self {
        Self::new(200, 40)
    }
}

//! Model-agnostic generative UI gallery system.
//!
//! Replaces op-gemma generators with an inference loop that reads sealed plugin blobs,
//! accepts operator guidance via Antigravity chat UI, and generates json-render.dev specs.

use anyhow::Result;
use clap::{Parser, Subcommand};
use tracing_subscriber::EnvFilter;

use op_gallery_gen::{
    GalleryGenConfig,
    context::GenerationContext,
    inference::InferenceLoop,
    validator::SpecValidator,
    admission::GalleryAdmission,
};

#[derive(Parser)]
#[command(name = "op-gallery-gen")]
#[command(about = "Model-agnostic generative UI gallery system")]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    /// Generate UI specs for the gallery
    Generate {
        /// Target number of specs to generate
        #[arg(short, long, default_value = "200")]
        target: usize,

        /// ZeroClaw HTTP endpoint
        #[arg(long, default_value = "http://localhost:8082")]
        endpoint: String,

        /// Enable MCP tool layer
        #[arg(long)]
        mcp: bool,

        /// Enable Qdrant semantic search
        #[arg(long)]
        qdrant: bool,

        /// Operator guidance text
        #[arg(short, long)]
        guidance: Option<String>,
    },

    /// Validate a spec file
    Validate {
        /// Path to spec JSON file
        #[arg(short, long)]
        file: String,
    },

    /// Show gallery statistics
    Stats,
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::from_default_env())
        .init();

    let cli = Cli::parse();

    match cli.command {
        Commands::Generate { target, endpoint, mcp, qdrant, guidance } => {
            run_generation(target, endpoint, mcp, qdrant, guidance).await?;
        }
        Commands::Validate { file } => {
            run_validation(&file)?;
        }
        Commands::Stats => {
            run_stats();
        }
    }

    Ok(())
}

async fn run_generation(
    target: usize,
    endpoint: String,
    mcp: bool,
    qdrant: bool,
    guidance: Option<String>,
) -> Result<()> {
    tracing::info!("Starting gallery generation with target: {}", target);

    let config = GalleryGenConfig {
        target_count: target,
        zeroclaw_endpoint: endpoint.clone(),
        enable_mcp: mcp,
        enable_qdrant: qdrant,
        ..Default::default()
    };

    // TODO: Load plugin schemas from blobs
    let schemas = vec![];

    let mut ctx = GenerationContext::new(schemas);
    ctx.mcp_enabled = mcp;
    ctx.qdrant_enabled = qdrant;
    ctx.operator_guidance = guidance;

    let loop_ = InferenceLoop::new(config.zeroclaw_endpoint, config.max_turns);
    let validator = SpecValidator::new();
    let admission = GalleryAdmission::new(config.target_count, config.stable_core_max);

    let mut generated = 0;
    let mut attempts = 0;
    let max_attempts = target * 3; // Allow 3x attempts

    while generated < target && attempts < max_attempts {
        attempts += 1;
        tracing::info!("Generation attempt {} of {}", attempts, max_attempts);

        match loop_.generate(&ctx).await {
            Ok(gen_spec) => {
                let validation = validator.validate(&gen_spec.spec);

                if validation.valid {
                    let admit_result = admission.admit(&validation);

                    if admit_result.admitted {
                        generated += 1;
                        tracing::info!("Successfully admitted spec {} of {}", generated, target);
                    } else if let Some(reason) = admit_result.rejection_reason {
                        tracing::warn!("Spec rejected: {}", reason);
                    }
                } else {
                    tracing::warn!("Spec validation failed: {:?}", validation.errors);
                }
            }
            Err(e) => {
                tracing::error!("Generation failed: {}", e);
            }
        }
    }

    tracing::info!("Generation complete: {} specs generated in {} attempts", generated, attempts);
    Ok(())
}

fn run_validation(file: &str) -> Result<()> {
    use std::fs;

    let content = fs::read_to_string(file)?;
    let spec: serde_json::Value = serde_json::from_str(&content)?;

    let validator = SpecValidator::new();
    let result = validator.validate(&spec);

    if result.valid {
        println!("✓ Spec is valid");
        println!("Signature: {}", result.signature);
    } else {
        println!("✗ Spec validation failed:");
        for error in &result.errors {
            println!("  [{}] {}", error.code, error.message);
        }
    }

    Ok(())
}

fn run_stats() {
    let admission = GalleryAdmission::default();
    let stats = admission.stats();

    println!("Gallery Statistics:");
    println!("  Max size: {}", stats.max_size);
    println!("  Stable core max: {}", stats.stable_core_max);
    println!("  Current size: {}", stats.current_size);
    println!("  Available slots: {}", stats.available_slots);
}

