// ── Gallery Generation API ─────────────────────────────────────────────────

use axum::response::sse::{Event, Sse};
use futures::stream::{Stream, StreamExt};
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::sync::Arc;
use tokio::sync::RwLock;

lazy_static::lazy_static! {
    static ref GEN_STATE: Arc<GenerationState> = Arc::new(GenerationState::new());
}

struct GenerationState {
    running: AtomicBool,
    generated: AtomicUsize,
    attempts: AtomicUsize,
    target: AtomicUsize,
    stop_signal: AtomicBool,
}

impl GenerationState {
    fn new() -> Self {
        Self {
            running: AtomicBool::new(false),
            generated: AtomicUsize::new(0),
            attempts: AtomicUsize::new(0),
            target: AtomicUsize::new(0),
            stop_signal: AtomicBool::new(false),
        }
    }
}

#[derive(Debug, Deserialize)]
pub struct GalleryGenConfig {
    pub target_count: usize,
    pub enable_mcp: bool,
    pub enable_qdrant: bool,
    pub operator_guidance: String,
}

/// POST /gallery-gen/start - Start a generation session
pub async fn start_generation(
    Extension(_state): Extension<Arc<AppState>>,
    axum::Json(config): axum::Json<GalleryGenConfig>,
) -> Result<impl IntoResponse, StatusCode> {
    // Check if already running
    if GEN_STATE.running.load(Ordering::SeqCst) {
        return Err(StatusCode::CONFLICT);
    }

    // Initialize state
    GEN_STATE.running.store(true, Ordering::SeqCst);
    GEN_STATE.generated.store(0, Ordering::SeqCst);
    GEN_STATE.attempts.store(0, Ordering::SeqCst);
    GEN_STATE.target.store(config.target_count, Ordering::SeqCst);
    GEN_STATE.stop_signal.store(false, Ordering::SeqCst);

    // TODO: Spawn background task that calls op-gallery-gen
    // For now, return success - the SSE stream will provide updates

    let response = json!({
        "status": "started",
        "config": {
            "target_count": config.target_count,
            "enable_mcp": config.enable_mcp,
            "enable_qdrant": config.enable_qdrant,
        }
    });

    Ok(axum::Json(response))
}

/// POST /gallery-gen/stop - Stop a running generation session
pub async fn stop_generation(
    Extension(_state): Extension<Arc<AppState>>,
) -> Result<impl IntoResponse, StatusCode> {
    GEN_STATE.stop_signal.store(true, Ordering::SeqCst);

    let response = json!({
        "status": "stopping"
    });

    Ok(axum::Json(response))
}

/// GET /gallery-gen/stream - SSE stream for generation progress
pub async fn generation_stream(
    Extension(_state): Extension<Arc<AppState>>,
) -> Sse<impl Stream<Item = Result<Event, Infallible>>> {
    let stream = async_stream::stream! {
        // Send initial status
        yield Ok(Event::default().json_data(json!({
            "type": "status",
            "running": GEN_STATE.running.load(Ordering::SeqCst),
            "generated": GEN_STATE.generated.load(Ordering::SeqCst),
            "attempts": GEN_STATE.attempts.load(Ordering::SeqCst),
            "target": GEN_STATE.target.load(Ordering::SeqCst),
        })).unwrap());

        yield Ok(Event::default().json_data(json!({
            "type": "log",
            "level": "info",
            "message": "Gallery generation SSE stream connected. Integration with op-gallery-gen pending."
        })).unwrap());

        // Keep connection alive with periodic updates
        let mut interval = tokio::time::interval(tokio::time::Duration::from_secs(5));
        loop {
            interval.tick().await;

            let running = GEN_STATE.running.load(Ordering::SeqCst);

            if !running {
                yield Ok(Event::default().json_data(json!({
                    "type": "complete",
                    "generated": GEN_STATE.generated.load(Ordering::SeqCst),
                    "attempts": GEN_STATE.attempts.load(Ordering::SeqCst),
                })).unwrap());
                break;
            }

            if GEN_STATE.stop_signal.load(Ordering::SeqCst) {
                yield Ok(Event::default().json_data(json!({
                    "type": "log",
                    "level": "info",
                    "message": "Generation stopped by operator"
                })).unwrap());

                GEN_STATE.running.store(false, Ordering::SeqCst);

                yield Ok(Event::default().json_data(json!({
                    "type": "complete",
                    "generated": GEN_STATE.generated.load(Ordering::SeqCst),
                    "attempts": GEN_STATE.attempts.load(Ordering::SeqCst),
                })).unwrap());
                break;
            }

            // Send heartbeat
            yield Ok(Event::default().json_data(json!({
                "type": "status",
                "running": running,
                "generated": GEN_STATE.generated.load(Ordering::SeqCst),
                "attempts": GEN_STATE.attempts.load(Ordering::SeqCst),
                "target": GEN_STATE.target.load(Ordering::SeqCst),
            })).unwrap());
        }
    };

    Sse::new(stream)
}

